import sys
import xml.etree.ElementTree as ET
from collections import defaultdict

def validate_xml(xml_path):
    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()
        if root.tag != 'config':
            print(f"ERROR: Root element must be <config>", file=sys.stderr)
            sys.exit(2)
        counters = root.find('counters')
        if counters is None:
            print(f"ERROR: <counters> element is missing", file=sys.stderr)
            sys.exit(2)
        if len(counters) != 1:
            print(f"ERROR: <counters> must contain exactly one element", file=sys.stderr)
            sys.exit(2)
        counter = counters.find('counter')
        if counter is None:
            print(f"ERROR: <counter> element is missing", file=sys.stderr)
            sys.exit(2)
        if len(counter.attrib.get('name')) == 0:
            print(f"ERROR: <counter> must have a non-empty name attribute", file=sys.stderr)
            sys.exit(2)
        return True
    except (IOError, ET.ParseError) as e:
        print(f"ERROR: Failed to read or parse XML file", file=sys.stderr)
        sys.exit(2)

def process_log(xml_path, log_path):
    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()
        counter_names = {counter.attrib['name'] for counter in root.findall('counters/counter')}
        counters = defaultdict(int)
        for name in counter_names:
            counters[name] = 0
    except Exception:
        print(f"ERROR: Failed to parse XML", file=sys.stderr)
        sys.exit(2)

    try:
        with open(log_path, 'r') as f:
            for line in f:
                stripped_line = line.strip()
                if not stripped_line:
                    continue
                tokens = stripped_line.split()
                if not tokens:
                    continue
                category = tokens[0]
                if category in counter_names:
                    counters[category] += 1
                else:
                    print(f"WARN: Unknown category '{category}'", file=sys.stderr)
    except IOError as e:
        print(f"ERROR: Failed to read log file", file=sys.stderr)
        sys.exit(2)

    return counters

def main():
    if len(sys.argv) != 3:
        print(f"ERROR: Usage: python {sys.argv[0]} <config.xml> <log_file>", file=sys.stderr)
        sys.exit(2)

    xml_path = sys.argv[1]
    log_path = sys.argv[2]

    if not validate_xml(xml_path):
        sys.exit(2)

    counters = process_log(xml_path, log_path)

    for name in sorted(counters.keys()):
        print(f"{name}={counters[name]}")

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET
from collections import defaultdict

def parse_xml(xml_path):
    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()
    except (IOError, ET.ParseError):
        sys.stderr.write("ERROR: Failed to read or parse XML file\n")
        sys.exit(2)

    if root.tag != "config":
        sys.stderr.write("ERROR: Root element must be 'config'\n")
        sys.exit(2)

    counters = root.find("counters")
    if counters is None:
        sys.stderr.write("ERROR: Missing 'counters' child of 'config'\n")
        sys.exit(2)

    valid_names = set()
    for counter in counters.findall("counter"):
        name = counter.get("name")
        if name is None:
            sys.stderr.write("ERROR: Missing 'name' attribute in counter\n")
            sys.exit(2)
        valid_names.add(name)

    return valid_names

def process_log(log_path, valid_names):
    counters = defaultdict(int)
    try:
        with open(log_path, "r") as f:
            for line in f:
                stripped = line.rstrip()
                if not stripped:
                    continue
                tokens = stripped.split()
                if not tokens:
                    continue
                category = tokens[0]
                if category in valid_names:
                    counters[category] += 1
                else:
                    sys.stderr.write(f"WARN: Unknown category '{category}'\n")
    except IOError:
        sys.stderr.write("ERROR: Failed to read log file\n")
        sys.exit(2)

    return counters

def main():
    if len(sys.argv) != 3:
        sys.stderr.write("ERROR: Incorrect number of arguments\n")
        sys.exit(2)

    xml_path = sys.argv[1]
    log_path = sys.argv[2]

    valid_names = parse_xml(xml_path)
    counters = process_log(log_path, valid_names)

    sorted_counters = sorted(counters.items())
