import sys
import xml.etree.ElementTree as ET
from collections import defaultdict

def validate_xml(xml_path):
    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()
        if root.tag != 'config':
            return False
        counters_elem = root.find('counters')
        if counters_elem is None or counters_elem.tag != 'counters':
            return False
        for counter in counters_elem.findall('counter'):
            if 'name' not in counter.attrib:
                return False
        return True
    except (IOError, ET.ParseError):
        return False

def process_log(xml_path, log_path):
    if not validate_xml(xml_path):
        print(f"ERROR: Invalid XML configuration", file=sys.stderr)
        sys.exit(2)

    try:
        with open(xml_path, 'r') as f:
            xml_content = f.read()
        root = ET.fromstring(xml_content)
        counters = {counter.attrib['name'] for counter in root.findall('counters/counter')}
    except IOError:
        print(f"ERROR: Could not read XML configuration file", file=sys.stderr)
        sys.exit(2)

    counters_count = defaultdict(int)
    try:
        with open(log_path, 'r') as f:
            for line in f:
                stripped_line = line.rstrip()
                if not stripped_line:
                    continue
                tokens = stripped_line.split()
                if not tokens:
                    continue
                category = tokens[0]
                if category in counters:
                    counters_count[category] += 1
                else:
                    print(f"WARN: Unknown category '{category}'", file=sys.stderr)
    except IOError:
        print(f"ERROR: Could not read log file", file=sys.stderr)
        sys.exit(2)

    sorted_counters = sorted(counters_count.items())
    for name, count in sorted_counters:
        print(f"{name}={count}")

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print(f"ERROR: Expected two arguments: XML config and log file", file=sys.stderr)
        sys.exit(2)

    process_log(sys.argv[1], sys.argv[2])

